<script setup>import {ref} from 'vue';const theme=ref(localStorage.getItem('fs-theme')||'dark');function save(){localStorage.setItem('fs-theme',theme.value);location.reload()}</script><template><h1>Ayarlar</h1><div class="card"><h2>Görünüm</h2><select class="field" v-model="theme"><option value="dark">Koyu tema</option><option value="light">Açık tema</option></select><button class="btn" @click="save">Uygula</button></div><br><div class="card"><h2>Bildirimler</h2><p class="muted">Mention bildirimleri yalnızca FlameStore içinde gösterilir. Sistem push bildirimi gönderilmez.</p></div></template>